// ── GibWork ────────────────────────────────────────────────────
async function executeGibWork(method, input) {
    switch (method.name) {
        case 'listBounties': {
            try {
                const status = input.status ?? 'open';
                const limit = input.limit ?? 20;
                const res = await fetch(`${GIBWORK_API}/v1/bounties?status=${status}&limit=${limit}`);
                if (!res.ok)
                    return { error: `GibWork API error: ${res.status}`, bounties: [] };
                return await res.json();
            }
            catch (err) {
                return { error: String(err), bounties: [] };
            }
        }
        default:
            return {
                status: 'instruction_ready',
                protocol: 'gibwork',
                method: method.name,
                params: input,
                message: `GibWork ${method.name} instruction prepared. Sign and submit.`,
            };
    }
}
